  ],
  "claims": [
    {
      "claim": "Direct human absolute oral bioavailability values for steroid-like molecules are consistently below 20%: β-sitosterol 0.41% (C01, C14, C20), testosterone 3.66% (C09), testosterone undecanoate 6.8% (C11, C24), danazol 11–19% in the fasted state (C04, C07, C12, C25), and abiraterone acetate <10% fasted (C10, C16, C23). This establishes a transferable low-F pattern for the query's steroid class.",
      "card_ids": ["C01", "C04", "C07", "C09", "C10", "C11", "C12", "C14", "C16", "C20", "C23", "C24", "C25"]
    },
    {
      "claim": "Phenolic steroids undergo extensive first-pass conjugation and efflux: fulvestrant's poor oral bioavailability is attributed to UGT/SULT inactivation in the GI tract and liver (C36), estradiol undergoes intestinal Phase II metabolism to glucuronide/sulfate conjugates (C71, C79), and estriol is a P-gp substrate with an efflux ratio of ~3.2 that collapses in the presence of a P-gp inhibitor (C77, C78). The query contains a phenol and a 1,2-diol, matching this presystemic-loss liability.",
      "card_ids": ["C36", "C71", "C77", "C78", "C79"]
    },
    {
      "claim": "L5 high-permeability records for hydrocortisone, buprenorphine, and samidorphan are not query-specific and do not contradict a low F prediction, because high intestinal permeability can coexist with extensive presystemic metabolism and low oral bioavailability.",
      "card_ids": ["C68", "C70", "C72", "C73", "C74", "C76"]
    },
    {
      "claim": "Ethinyl estradiol being a substrate for P-gp, BCRP, CYP3A, and UGT (C69) is mechanism-only evidence and is not a direct oral-bioavailability result; it does not outweigh the consistent measured low-F pattern for phenolic steroids.",
      "card_ids": ["C69"]
    },
    {
      "claim": "Conflicting high-F descriptions for stigmasterol (C30) and DMAU (C40) are not transferable to the query or are contradicted by measured low-F data for the same compound (C06, C38), so they do not support a high prediction.",
      "card_ids": ["C30", "C40", "C06", "C38"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C69", "C71", "C77", "C78", "C79"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific human PK, AUC, Cmax, dose, or formulation data are available.",
    "L5 gut-wall efflux and intestinal-metabolism records are for other phenolic steroids (estradiol, estriol, ethinyl estradiol) rather than the query.",
    "First-pass conjugation for the query is inferred from structural similarity and analog mechanism, not measured directly.",
    "Query-specific solubility, permeability, and efflux are not experimentally measured.",
    "The exact query structure is not matched to a training context with a measured F value."
  ],
  "decision_summary": "Prediction remains low and is strengthened by L5. Direct human absolute F values for steroid-like molecules are consistently below 20%, and the query's phenol plus 1,2-diol matches the well-documented presystemic conjugation/efflux liability seen for fulvestrant, estradiol, and estriol. L5 gut-wall metabolism and efflux records add mechanistic support for F < 20% but are not direct query measurements; no new evidence overturns the low prediction."
}

